const registry_name = 'progress_monitor';
const display_name = 'Progress Monitor';
const version = '1.0.0';
const author = 'Your Name';
const description = 'Monitors macro playback progress';

const context = mm.getContext();
let startTime = null;

mm.on('io.github.samera2022.samacros.api.event.events.BeforePlaybackStartEvent', 
    (event) => {
        startTime = event.getTimestamp();
        const repeats = event.getRepeatCount();
        mm.log('=== Playback Started ===');
        mm.log('Repeats: ' + repeats);
        context.showToast('Starting', 'Macro playback started');
    });

mm.on('io.github.samera2022.samacros.api.event.events.OnLoopCompleteEvent', 
    (event) => {
        const completed = event.getCompletedIterations();
        const remaining = event.getRemainingIterations();
        const elapsed = event.getTimestamp() - startTime;

        const percent = Math.round((completed / (completed + remaining)) * 100);
        mm.log('[' + percent + '%] Loop ' + completed + ' - ' + 
                Math.round(elapsed / 1000) + 's elapsed');
    });

examples.example2-code:
const registry_name = 'safe_executor';
const display_name = 'Safe Executor';
const version = '1.0.0';
const author = 'Your Name';
const description = 'Validates before execution';

const MAX_REPEATS = 100;
const MIN_ACTIONS = 1;

mm.on('io.github.samera2022.samacros.api.event.events.BeforePlaybackStartEvent', 
    (event) => {
        try {
            const repeats = event.getRepeatCount();
            const context = mm.getContext();
            const macro = context.getMacroInfo();
            const actions = macro.getActionsCount();

            // Check repeat count
            if (repeats < 1 || repeats > MAX_REPEATS) {
                event.setCancelled(true);
                context.showToast('Error', 'Invalid repeats: ' + repeats);
                mm.log('BLOCKED: Invalid repeat count');
                return;
            }

            // Check action count
            if (actions < MIN_ACTIONS) {
                event.setCancelled(true);
                context.showToast('Error', 'Macro is empty');
                mm.log('BLOCKED: No actions in macro');
                return;
            }

            mm.log('APPROVED: ' + repeats + 'x with ' + actions + ' actions');
            context.showToast('Ready', 'Playback validated');

        } catch (error) {
            event.setCancelled(true);
            mm.log('ERROR: ' + error);
        }
    });

