const version = '1.0.0';
const author = 'Your Name';
const description = 'Detects specific color at coordinates';

const CHECK_X = 100;
const CHECK_Y = 100;
const TARGET_RED = 255;
const TARGET_GREEN = 0;
const TARGET_BLUE = 0;

