        // Check every 5 loops
        if (event.getCompletedIterations() % 5 === 0) {
            const color = context.getPixelColor(CHECK_X, CHECK_Y);

            if (color.getRed() === TARGET_RED &&
                color.getGreen() === TARGET_GREEN &&
                color.getBlue() === TARGET_BLUE) {

                mm.log('TARGET COLOR FOUND at iteration ' + 
                        event.getCompletedIterations());
                context.showToast('Found', 'Target color detected!');
            }
        }
    });

examples.example4-code:
const registry_name = 'log_analyzer';
const display_name = 'Log Analyzer';
const version = '1.0.0';
const author = 'Your Name';
const description = 'Analyzes execution logs';

let stepCounts = {};

mm.on('io.github.samera2022.samacros.api.event.events.BeforeStepExecuteEvent', 
    (event) => {
        const stepIndex = event.getStepIndex();
        stepCounts[stepIndex] = (stepCounts[stepIndex] || 0) + 1;
    });

mm.on('io.github.samera2022.samacros.api.event.events.OnPlaybackAbortedEvent', 
    (event) => {
        mm.log('=== Execution Summary ===');
        for (const step in stepCounts) {
            mm.log('Step ' + step + ': executed ' + stepCounts[step] + ' times');
        }
    });

mm.cleanup = function() {
    const str = 'Cleanup: Total steps tracked: ' + Object.keys(stepCounts).length;
    mm.log(str);
};

